    P=[]
    for bi in range(oh):
        row=[]
        for bj in range(ow):
            blk=I[rs[bi]:rs[bi+1],cs[bj]:cs[bj+1]]
            cnt=dict(C(map(int,blk.flat)))
            cc={k:v for k,v in cnt.items() if k!=1}
            v=max(cc,key=lambda x:cc[x]) if cc else -1
            row.append(v)
        P.append(row)
    return np.array(P)
for n in range(1,9):
    I=np.array(G[f'Demo pair {n} input']); O=np.array(G[f'Demo pair {n} output'])
    P=f(I,O)
    print('demo',n,'noise-mode:',np.array_equal(P,O))
